const axios = require('axios');

async function getServiceToken() {
  const tokenUrl = process.env.TOKEN_URL;
  const clientId = process.env.CLIENT_ID;
  const clientSecret = process.env.CLIENT_SECRET;
  const scope = 'api.read api.write';

  const params = new URLSearchParams();
  params.append('grant_type', 'client_credentials');
  params.append('client_id', clientId);
  params.append('client_secret', clientSecret);
  params.append('scope', scope);

  try {
    const response = await axios.post(tokenUrl, params, {
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
      },
    });

    const { access_token, expires_in } = response.data;

    // Cache the token to avoid requesting a new one on every call
    const tokenExpiry = Date.now() + expires_in * 1000 - 60000; // 1 min buffer
    return { accessToken: access_token, expiresAt: tokenExpiry };
  } catch (error) {
    console.error('Failed to obtain client credentials token:', error.response?.data);
    throw error;
  }
}

// Usage: get token, cache it, refresh before expiry
const tokenCache = { accessToken: null, expiresAt: null };

async function callProtectedApi() {
  if (!tokenCache.accessToken || Date.now() > tokenCache.expiresAt) {
    const token = await getServiceToken();
    tokenCache.accessToken = token.accessToken;
    tokenCache.expiresAt = token.expiresAt;
  }

  const response = await axios.get('https://api.example.com/data', {
    headers: { Authorization: `Bearer ${tokenCache.accessToken}` },
  });

  return response.data;
}

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import jwksClient from 'jwks-rsa';

const client = jwksClient({ jwksUri: process.env.JWKS_URI });

const REQUIRED_SCOPE = 'api.read';

export async function requireClientCredentials(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }

  const token = authHeader.substring(7);

  try {
    // Verify the token signature using the JWKS endpoint
    const decoded = jwt.decode(token, { complete: true }) as jwt.JwtPayload;
    if (!decoded) {
      return res.status(401).json({ error: 'Invalid token' });
    }

    // Fetch the signing key
    const signingKey = await new Promise< string>((resolve, reject) => {
      client.getSigningKey(decoded.header.kid, (err, key) => {
        if (err) reject(err);
        resolve(key.getPublicKey());
      });
    });

    const payload = jwt.verify(token, signingKey, {
      audience: process.env.CLIENT_ID,
      issuer: process.env.ISSUER,
      algorithms: ['RS256'],
    }) as jwt.JwtPayload;

    // Verify this token was issued via client_credentials (no user sub)
    if (payload.sub) {
      return res.status(403).json({ error: 'Token must be from client credentials' });
    }

    // Require the specific scope this endpoint needs
    const scopes = payload.scope?.split(' ') || [];
    if (!scopes.includes(REQUIRED_SCOPE)) {
      return res.status(403).json({ error: `Insufficient scope, requires: ${REQUIRED_SCOPE}` });
    }

    req.clientId = payload.client_id;
    next();
  } catch (error) {
    console.error('Token validation error:', error);
    return res.status(401).json({ error: 'Invalid token' });
  }
}
